typedef struct {
  int *data;
  int *mins;
  int top;
  int capacity;
} MinStack;

MinStack *minStackCreate(void) {
  MinStack *obj = (MinStack *)malloc(sizeof(MinStack));
  obj->capacity = 100000;
  obj->data = (int *)malloc(sizeof(int) * obj->capacity);
  obj->mins = (int *)malloc(sizeof(int) * obj->capacity);
  obj->top = 0;
  return obj;
}

void minStackPush(MinStack *obj, int x) {
  obj->data[obj->top] = x;
  int m = x;
  if (obj->top > 0 && obj->mins[obj->top - 1] < m) m = obj->mins[obj->top - 1];
  obj->mins[obj->top] = m;
  obj->top++;
}

void minStackPop(MinStack *obj) {
  if (obj->top > 0) obj->top--;
}

int minStackTop(MinStack *obj) {
  return obj->data[obj->top - 1];
}

int minStackGetMin(MinStack *obj) {
  return obj->mins[obj->top - 1];
}

void minStackFree(MinStack *obj) {
  free(obj->data);
  free(obj->mins);
  free(obj);
}

class MinStack {
  stack<int> data;
  stack<int> mins;

public:
  MinStack() {}
  void push(int x) {
    data.push(x);
    mins.push(mins.empty() ? x : min(x, mins.top()));
  }
  void pop() {
    data.pop();
    mins.pop();
  }
  int top() { return data.top(); }
  int getMin() { return mins.top(); }
};

type MinStack struct {
	data []int
	mins []int
}

func Constructor() MinStack {
	return MinStack{}
}

func (m *MinStack) Push(x int) {
	m.data = append(m.data, x)
	cur := x
	if len(m.mins) > 0 && m.mins[len(m.mins)-1] < cur {
		cur = m.mins[len(m.mins)-1]
	}
	m.mins = append(m.mins, cur)
}

func (m *MinStack) Pop() {
	m.data = m.data[:len(m.data)-1]
	m.mins = m.mins[:len(m.mins)-1]
}

func (m *MinStack) Top() int {
	return m.data[len(m.data)-1]
}

func (m *MinStack) GetMin() int {
	return m.mins[len(m.mins)-1]
}

class MinStack {
  private Deque<Integer> data = new ArrayDeque<>();
  private Deque<Integer> mins = new ArrayDeque<>();

  public MinStack() {}

  public void push(int x) {
    data.push(x);
    mins.push(mins.isEmpty() ? x : Math.min(x, mins.peek()));
  }

  public void pop() {
    data.pop();
    mins.pop();
  }

  public int top() {
    return data.peek();
  }

  public int getMin() {
    return mins.peek();
  }
}

class MinStack:
    def __init__(self):
        self.data = []
        self.mins = []

    def push(self, x: int) -> None:
        self.data.append(x)
        self.mins.append(x if not self.mins else min(x, self.mins[-1]))

    def pop(self) -> None:
        self.data.pop()
        self.mins.pop()

    def top(self) -> int:
        return self.data[-1]

    def getMin(self) -> int:
        return self.mins[-1]

impl MinStack {
  pub fn new() -> Self {
    MinStack {
      data: vec![],
      mins: vec![],
    }
  }

  pub fn push(&mut self, x: i32) {
    self.data.push(x);
    let cur = if self.mins.is_empty() {
      x
    } else {
      x.min(*self.mins.last().unwrap())
    };
    self.mins.push(cur);
  }

  pub fn pop(&mut self) {
    self.data.pop();
    self.mins.pop();
  }

  pub fn top(&self) -> i32 {
    *self.data.last().unwrap()
  }

  pub fn get_min(&self) -> i32 {
    *self.mins.last().unwrap()
  }
}

class MinStack {
  private data: number[] = [];
  private mins: number[] = [];

  push(x: number): void {
    this.data.push(x);
    this.mins.push(this.mins.length === 0 ? x : Math.min(x, this.mins[this.mins.length - 1]));
  }

  pop(): void {
    this.data.pop();
    this.mins.pop();
  }

  top(): number {
    return this.data[this.data.length - 1];
  }

  getMin(): number {
    return this.mins[this.mins.length - 1];
  }
}
